import roman, io, contextlib
from roman import to_roman
assert to_roman(1)=="I" and to_roman(3)=="III" and to_roman(4)=="IV" and to_roman(9)=="IX"
assert to_roman(14)=="XIV" and to_roman(40)=="XL" and to_roman(90)=="XC" and to_roman(400)=="CD"
assert to_roman(1994)=="MCMXCIV" and to_roman(2026)=="MMXXVI" and to_roman(3999)=="MMMCMXCIX"
V={"I":1,"V":5,"X":10,"L":50,"C":100,"D":500,"M":1000}
def dec(s):
    t=0
    for i,c in enumerate(s):
        v=V[c]
        if i+1<len(s) and V[s[i+1]]>v: t-=v
        else: t+=v
    return t
for n in range(1,4000): assert dec(to_roman(n))==n, n
for bad in (0,-1,4000):
    try: to_roman(bad); raise SystemExit("no VE")
    except ValueError: pass
for bad in ("5",5.0,True):
    try: to_roman(bad); raise SystemExit("no TE")
    except TypeError: pass
print("ALL OK", sorted(n for n in dir(roman) if not n.startswith("_")))
